      --button-dim: 0.5;
      animation: none;
    }
  }

  /* block: the full width of its container, label still centered. */
  .button[data-block] {
    display: grid;
    width: 100%;
  }
}

"use client";

import { isValidElement, type ComponentProps, type MouseEvent, type ReactNode } from "react";
import { TextMorph } from "../text-morph/text-morph";
import styles from "./button.module.css";
import { useDelayedBusy } from "./use-delayed-busy";

type ButtonProps = ComponentProps<"button"> & {
  variant?: "primary" | "secondary" | "ghost" | "danger";
  size?: "sm" | "md" | "lg";
  /** Work is in flight: presses are ignored at once, focus stays. The shimmer
   *  (and `busyLabel`) shows only once it has lasted 300ms, then for 400ms at least. */
  busy?: boolean;
  /** The label while the busy state shows, like "Saving…". Morphs from the label. */
  busyLabel?: ReactNode;
  /** Fills its container's width: the main action of a narrow form or a sheet. */
  block?: boolean;
};

export function Button({
  variant = "primary",
  size = "md",
  busy = false,
  busyLabel,
  block = false,
  type = "button",
  className,
  children,
  onClick,
  ...props
}: ButtonProps) {
  const shown = useDelayedBusy(busy);
  // One element and no text, named by aria-label: an icon button, drawn as a capsule.
  const iconOnly = isValidElement(children) && Boolean(props["aria-label"]);
  const label = shown && busyLabel !== undefined ? busyLabel : children;

  function handleClick(event: MouseEvent<HTMLButtonElement>) {
    // Busy is not disabled: the button keeps focus and its tab stop.
    if (busy) {
      event.preventDefault();
      return;
    }
    onClick?.(event);
  }

  return (
    <button
      type={type}
      data-variant={variant}
      data-size={size}
      data-block={block || undefined}
      aria-busy={busy || undefined}
      aria-disabled={busy || undefined}
      data-busy-shown={shown || undefined}
      data-icon-only={iconOnly || undefined}
      className={className ? `${styles.button} ${className}` : styles.button}
      onClick={handleClick}
      {...props}
    >
      <span className={styles.content}>
        {typeof label === "string" ? <TextMorph>{label}</TextMorph> : label}
      </span>
    </button>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";

/**
 * Whether to show that work is running. Fast work never shows: the busy
 * state appears only once `busy` has lasted `delay` ms, and once it has
 * appeared it stays at least `minimum` ms, so it never flickers in and out.
 */
export function useDelayedBusy(busy: boolean, delay = 300, minimum = 400) {
  const [shown, setShown] = useState(false);
  const since = useRef(0);

  useEffect(() => {
    if (busy === shown) return;
    const wait = busy ? delay : Math.max(0, minimum - (performance.now() - since.current));
    const timer = window.setTimeout(() => {
      if (busy) since.current = performance.now();
      setShown(busy);
    }, wait);
    return () => window.clearTimeout(timer);
  }, [busy, shown, delay, minimum]);

  return shown;
}

@layer theme, base, components, utilities;

@layer components {
  .icon {
    flex-shrink: 0;
    width: var(--ui-icon-md);
    height: var(--ui-icon-md);
    overflow: visible;
    fill: none;
    stroke: currentColor;
    stroke-width: var(--ui-icon-stroke, 1.5);
    stroke-linecap: round;
    stroke-linejoin: round;
  }

  /* A chevron is one size everywhere (--ui-icon-chevron), a step under the
     icons around it. */
  .icon[data-icon^="chevron"] {
    width: var(--ui-icon-chevron);
    height: var(--ui-icon-chevron);
  }

  /* A disclosure chevron that points right and opens downward turns a
     quarter turn (data-turn="open"): changing axis, a morph between the two
     shapes reads as the arrow coming apart, so this one rotates, on the glide
     curve with no overshoot. Down/up chevrons morph instead. */
  .icon.icon[data-turn] {
    /* Doubled class: outranks a component's own `transition` on its chevron
       (usually its hover color), so both are listed here. */
    transition:
      rotate var(--ui-dur-base) var(--ui-ease-glide),
      color var(--ui-dur-instant) var(--ui-ease-color),
      opacity var(--ui-dur-instant) var(--ui-ease-color);
  }

  .icon[data-turn="open"] {
    rotate: 90deg;
  }

  :is([dir="rtl"]) .icon[data-turn] {
    scale: -1 1;
  }

  :is([dir="rtl"]) .icon[data-turn="open"] {
    rotate: -90deg;
  }

  @media (prefers-reduced-motion: reduce) {
    .icon.icon[data-turn] {
      transition: color var(--ui-dur-instant) var(--ui-ease-color);
    }
  }

  /* The gap (3) must exceed any path plus margins so the dash never repeats. */
  .stroke {
    stroke-dasharray: var(--len, 1) 3;
    stroke-dashoffset: var(--on, 0);
    transform-box: fill-box;
    transform-origin: center;
    /* --icon-morph-ease: set to --ui-ease-glide where a morph should land
       without overshoot (a result, not a toggle). */
    transition:
      d var(--ui-dur-move) var(--icon-morph-ease, var(--ui-ease-move)),
      stroke-dasharray var(--ui-dur-move) var(--icon-morph-ease, var(--ui-ease-move)),
      stroke-dashoffset var(--ui-dur-move) var(--icon-morph-ease, var(--ui-ease-move)),
      rotate var(--ui-dur-move) var(--icon-morph-ease, var(--ui-ease-move)),
      translate var(--ui-dur-snap) var(--ui-ease-snap);
  }

  /* A stroke that leaves (copy's sheets as the check arrives) gets out of
     the way: it erases, fades and draws in slightly, all quickly, so the two
     shapes never tangle in the same spot. */
  .stroke[data-off] {
    stroke-dashoffset: var(--off, 1.3);
    opacity: 0;
    scale: 0.85;
    transition:
      stroke-dashoffset var(--ui-dur-fast) var(--ui-ease-exit),
      opacity var(--ui-dur-instant) var(--ui-ease-exit),
      scale var(--ui-dur-fast) var(--ui-ease-exit),
      translate var(--ui-dur-snap) var(--ui-ease-snap);
  }

  /* A stroke that arrives waits a beat for the old one to clear, then draws
     on in one clean pass. */
  .stroke[data-enter] {
    transition:
      stroke-dashoffset var(--ui-dur-base) var(--ui-ease-draw) calc(var(--ui-dur-instant) * 0.6),
      translate var(--ui-dur-snap) var(--ui-ease-snap);
  }

  /* Two strokes that meet end to end at rest (copy's sheet and rim): the
     moving one lands without overshoot, so the seam never opens, and the
     other erases in place along its path instead of fading and shrinking, so
     copy → check reads as one line opening at its corner. */
  .stroke.seam:not([data-enter]) {
    transition:
      d var(--ui-dur-glide) var(--ui-ease-glide),
      stroke-dasharray var(--ui-dur-glide) var(--ui-ease-glide),
      stroke-dashoffset var(--ui-dur-glide) var(--ui-ease-glide),
      translate var(--ui-dur-snap) var(--ui-ease-snap);
  }

  .stroke.seam[data-off] {
    opacity: 1;
    scale: none;
    transition:
      stroke-dashoffset var(--ui-dur-instant) var(--ui-ease-draw),
      translate var(--ui-dur-snap) var(--ui-ease-snap);
  }

  @starting-style {
    .icon[data-ready] .stroke[data-enter] {
      stroke-dashoffset: var(--off, 1.3);
    }
  }

  .block {
    stroke-width: 4;
  }

  /* Mask copy of a cut stroke: gaps the other strokes on both sides of it. */
  .cut {
    stroke: black;
    stroke-width: calc(var(--ui-icon-stroke, 1.5) * 3);
  }

  /* ---------- Parent hover ---------- */

  @media (hover: hover) {
    :is(button, a, [role="button"], [role="menuitem"]):hover:not(:disabled, [aria-disabled="true"]) .lid {
      translate: 0 -1px;
    }
    :is(button, a, [role="button"], [role="menuitem"]):hover:not(:disabled, [aria-disabled="true"]) .out {
      translate: 1px -1px;
    }
    :is(button, a, [role="button"], [role="menuitem"]):hover:not(:disabled, [aria-disabled="true"]) .drop {
      translate: 0 1px;
    }
    :is(button, a, [role="button"], [role="menuitem"]):hover:not(:disabled, [aria-disabled="true"]) .forward {
      translate: 1px 0;
    }
  }

  :is(button, a, [role="button"], [role="menuitem"]):focus-visible .lid {
    translate: 0 -1px;
  }

  :is(button, a, [role="button"], [role="menuitem"]):focus-visible .out {
    translate: 1px -1px;
  }

  :is(button, a, [role="button"], [role="menuitem"]):focus-visible .drop {
    translate: 0 1px;
  }

  :is(button, a, [role="button"], [role="menuitem"]):focus-visible .forward {
    translate: 1px 0;
  }

  @media (prefers-reduced-motion: reduce) {
    .stroke,
    .stroke[data-off],
    .stroke[data-enter],
    .stroke.seam:not([data-enter]),
    .stroke.seam[data-off] {
      transition: none;
    }
  }
}

