export type IconName = keyof typeof ICONS;

/** Every name in the set, in table order. */
export const ICON_NAMES = Object.keys(ICONS) as IconName[];

type Live = { id: string; key: string; s: Stroke; on: boolean; enter: boolean };
type State = { name: IconName; gen: number; live: Live[] };

const table = ICONS as Record<IconName, Record<string, Stroke>>;

/** Command letters and argument counts: `d` interpolates only when these match. */
const shape = (d: string) =>
  (d.match(/[a-zA-Z][^a-zA-Z]*/g) ?? []).map((c) => c[0] + ((c.slice(1).match(/-?[\d.]+(?:e-?\d+)?/g) ?? []).length)).join();

let morphD: boolean | undefined;
const canMorphD = () => (morphD ??= typeof CSS !== "undefined" && CSS.supports("d", 'path("M0 0")'));

function morphs(from: Stroke, to: Stroke) {
  if (Boolean(from.block) !== Boolean(to.block) || Boolean(from.cut) !== Boolean(to.cut)) return false;
  return from.d === to.d || (canMorphD() && shape(from.d) === shape(to.d));
}

function initial(name: IconName): State {
  return {
    name,
    gen: 0,
    live: Object.entries(table[name]).map(([key, s]) => ({ id: `${key}.0`, key, s, on: true, enter: false })),
  };
}

function next(prev: State, name: IconName): State {
  const want = table[name];
  const gen = prev.gen + 1;
  const taken = new Set<string>();
  const live: Live[] = [];
  for (const l of [...prev.live].sort((a, b) => Number(b.on) - Number(a.on))) {
    const s = want[l.key];
    if (s && !taken.has(l.key) && morphs(l.s, s)) {
      taken.add(l.key);
      live.push({ ...l, s, on: true, enter: !l.on });
    } else {
      live.push({ ...l, on: false, enter: false });
    }
  }
  for (const [key, s] of Object.entries(want)) {
    if (!taken.has(key)) live.push({ id: `${key}.${gen}`, key, s, on: true, enter: true });
  }
  const gone = live.filter((l) => !l.on);
  const drop = new Set(gone.slice(0, Math.max(0, gone.length - 8)).map((l) => l.id));
  return { name, gen, live: live.filter((l) => !drop.has(l.id)) };
}

const HIDE = 0.3;

// CSS `d` is set only after the first change; until then the attribute draws.
function dash(l: Live, morphing: boolean): CSSProperties | undefined {
  const f = l.s.f ?? 0;
  const t = l.s.t ?? 1;
  const len = t - f;
  const off = f === 0 ? len + HIDE : -(1 + HIDE);
  const style = {
    d: morphing ? `path("${l.s.d}")` : undefined,
    rotate: l.s.rot ? `${l.s.rot}deg` : undefined,
    "--len": len === 1 ? undefined : len,
    "--on": f === 0 ? undefined : -f,
    "--off": off === 1 + HIDE ? undefined : off,
  } as CSSProperties;
  return Object.values(style).some((v) => v !== undefined) ? style : undefined;
}

export type IconProps = Omit<ComponentProps<"svg">, "children"> & { name: IconName };

export function Icon({ name, className, ...props }: IconProps) {
  const [state, setState] = useState(() => initial(name));
  const mask = `icon-cut-${useId()}`;
  if (state.name !== name) setState(next(state, name));

  const cuts = state.live.filter((l) => l.s.cut);
  const path = (l: Live, extra?: string) => (
    <path
      key={l.id + (extra ?? "")}
      d={l.s.d}
      pathLength={1}
      className={[styles.stroke, l.s.block && styles.block, l.s.seam && styles.seam, l.s.fx && styles[l.s.fx], extra].filter(Boolean).join(" ")}
      data-off={l.on ? undefined : ""}
      data-enter={l.enter ? "" : undefined}
      style={dash(l, state.gen > 0)}
      onTransitionEnd={
        l.on || extra
          ? undefined
          : (e) => {
              if (e.propertyName === "stroke-dashoffset") {
                setState((s) => ({ ...s, live: s.live.filter((x) => x.id !== l.id || x.on) }));
              }
            }
      }
    />
  );

  return (
    // Size attributes keep it from drawing huge before CSS loads.
    <svg
      viewBox="0 0 16 16"
      width="16"
      height="16"
      aria-hidden="true"
      data-icon={name}
      data-ready={state.gen > 0 ? "" : undefined}
      className={className ? `${styles.icon} ${className}` : styles.icon}
      {...props}
    >
      {cuts.length > 0 && (
        <mask id={mask} maskUnits="userSpaceOnUse" x="0" y="0" width="16" height="16">
          <rect width="16" height="16" fill="white" stroke="none" />
          {cuts.map((l) => path(l, styles.cut))}
        </mask>
      )}
      <g mask={cuts.length > 0 ? `url(#${mask})` : undefined}>{state.live.filter((l) => !l.s.cut).map((l) => path(l))}</g>
      {cuts.map((l) => path(l))}
    </svg>
  );
}

@layer theme, base, components, utilities;

.label {
  composes: wrap from "../text/text.module.css";
}

.description {
  composes: wrap from "../text/text.module.css";
}

@layer components {
  /* The segmented control in miniature: a sunken track with a raised pill in it.
     The visible track is --switch-h tall; its hit area is a control height
     (--switch-hit), so it lines up with a button of that size beside it. */
  .root {
    --switch-h: 24px;
    --switch-w: 44px;
    --switch-pad: 3px;
    --switch-hit: var(--ui-control-md);
    --switch-thumb-h: calc(var(--switch-h) - var(--switch-pad) * 2);
    /* A capsule, like every pressable thing: wider than tall. */
    --switch-thumb-w: calc(var(--switch-thumb-h) * var(--ui-capsule));
    --switch-travel: calc(var(--switch-w) - var(--switch-thumb-w) - var(--switch-pad) * 2);
    /* How far a press stretches the thumb toward its new side. */
    --switch-reach: 3px;

    /* Off: the segmented control's track and pill. The track takes the strong
       fill: with no labels in it, the faint one barely reads as a control. */
    --switch-track: var(--ui-fill-strong);
    --switch-track-hover: color-mix(in oklch, var(--ui-foreground) 11%, transparent);
    --switch-track-press: color-mix(in oklch, var(--ui-foreground) 14%, transparent);
    /* The raised surface in light. In dark a knob the color of the surface reads
       as a hole in a dark track, so it's a light gray there, the slider's too. */
    --switch-thumb: light-dark(var(--ui-surface), color-mix(in oklch, var(--ui-foreground) 86%, var(--ui-surface)));

    position: relative;
    display: inline-flex;
    /* Puts the switch on the label's first line (see .control). */
    align-items: baseline;
    gap: var(--ui-space-3);
    max-width: 100%;
    color: var(--ui-foreground);
    font: var(--ui-weight-regular) var(--ui-text-md) / var(--ui-leading-md) var(--ui-font-sans);
    cursor: pointer;
    user-select: none;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
  }

  .root[data-size="sm"] {
    --switch-h: 20px;
    --switch-w: 36px;
    --switch-pad: 2px;
    --switch-hit: var(--ui-control-sm);
  }

  .root[data-side="end"] {
    display: flex;
    flex-direction: row-reverse;
    justify-content: space-between;
    gap: var(--ui-space-5);
    width: 100%;
  }

  /* On: the accent, as on a checked checkbox and a slider's range. */
  .root:has(.track[data-checked]) {
    --switch-track: var(--ui-accent);
    --switch-track-hover: color-mix(in oklch, var(--ui-accent) 86%, var(--ui-on-accent));
    --switch-track-press: color-mix(in oklch, var(--ui-accent) 78%, var(--ui-on-accent));
    --switch-thumb: var(--ui-on-accent);
  }

  /* With no text its baseline is its bottom edge; the shift centers it on the first line's capitals. */
  .control {
    --optical: calc(var(--switch-h) / 2 - 0.5cap);
    position: relative;
    flex-shrink: 0;
    width: var(--switch-w);
    height: var(--switch-h);
    margin-top: calc(var(--optical) * -1);
    translate: 0 var(--optical);
    /* The thumb animates insets; this keeps that layout contained. */
    contain: layout;
  }

  /* Without the `cap` unit (Safari before 17.2) --optical is invalid and the
     control drops onto the baseline, 2-6px high. The system faces' capitals
     are about 0.7em tall, so half of that stands in. */
  @supports not (height: 1cap) {
    .control {
      --optical: calc(var(--switch-h) / 2 - 0.35em);
    }
  }

  /* Without a label there's no line to sit on. */
  .control:only-child {
    margin-top: 0;
    translate: none;
  }

  /* The hit area: a control height, a little past the track's ends. Lays out nothing. */
  .control::after {
    content: "";
    position: absolute;
    inset: calc((var(--switch-h) - var(--switch-hit)) / 2) -2px;
  }

  /* Base UI's Switch.Root: the focusable role="switch" element, drawn as the track. */
  .track {
    position: absolute;
    inset: 0;
    display: block;
    border-radius: var(--ui-radius-full);
    background: var(--switch-track);
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--ui-border-strong);
    /* Drives the focus ring color. */
    color: var(--ui-foreground);
    cursor: inherit;
    transition: background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  /* On: the accent fill is its own edge, like a checked checkbox, so no gray
     ring haloes the blue in dark mode. */
  .track[data-checked] {
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--ui-accent);
    color: var(--ui-on-accent);
    transition-duration: var(--ui-dur-fast);
  }

  /* Raised, like the segmented control's pill: placed by its two edges, so a
     press can stretch it toward its new side; logical insets cover RTL. */
  .thumb {
    position: absolute;
    top: var(--switch-pad);
    bottom: var(--switch-pad);
    inset-inline-start: var(--switch-pad);
    inset-inline-end: calc(var(--switch-pad) + var(--switch-travel));
    border-radius: var(--ui-radius-full);
    background: var(--switch-thumb);
    box-shadow:
      0 0 0 var(--ui-hairline) var(--ui-border-strong),
      var(--ui-shadow-control);
    color: var(--ui-muted);
    pointer-events: none;
    transition:
      inset-inline-start var(--ui-dur-glide) var(--ui-ease-glide),
      inset-inline-end var(--ui-dur-glide) var(--ui-ease-glide),
      background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .thumb[data-checked] {
    inset-inline-start: calc(var(--switch-pad) + var(--switch-travel));
    inset-inline-end: var(--switch-pad);
    /* On the accent, the thumb needs no ring: its light fill is the edge. */
    box-shadow: var(--ui-shadow-control);
    color: var(--ui-accent);
  }

  /* Press: the thumb reaches toward its new side at once; the release glides on from there. */
  .root:active:not([data-disabled], [data-busy]) .thumb {
    transition-duration: var(--ui-dur-press);
  }

  .root:active:not([data-disabled], [data-busy]) .thumb[data-unchecked] {
    inset-inline-end: calc(var(--switch-pad) + var(--switch-travel) - var(--switch-reach));
  }

  .root:active:not([data-disabled], [data-busy]) .thumb[data-checked] {
    inset-inline-start: calc(var(--switch-pad) + var(--switch-travel) - var(--switch-reach));
  }

  @media (hover: hover) {
    .root:hover:not([data-disabled], [data-busy]) .track {
      background: var(--switch-track-hover);
    }
  }

  .root:active:not([data-disabled], [data-busy]) .track {
    background: var(--switch-track-press);
    transition-duration: var(--ui-dur-press);
  }

  .track:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  /* Busy: a working dot breathes in the thumb, once the save has taken 300ms. */
  .thumb::after {
    content: "";
    position: absolute;
    inset: 0;
    margin: auto;
    width: 6px;
    height: 6px;
    border-radius: var(--ui-radius-full);
    background: currentColor;
    opacity: 0;
    transition: opacity var(--ui-dur-instant) var(--ui-ease-color);
  }

  .root[data-busy-shown] .thumb::after {
    opacity: 1;
    transition: opacity var(--ui-dur-fast) var(--ui-ease-enter);
    animation: switch-working var(--ui-dur-pulse) var(--ui-ease-pulse) infinite alternate;
  }

  @keyframes switch-working {
    from {
      scale: 1;
    }
    to {
      scale: 0.6;
    }
  }

  .root[data-busy] {
    cursor: default;
  }

  .text {
    display: grid;
    gap: 2px;
    min-width: 0;
  }

  .label {
    font-weight: var(--ui-weight-medium);
  }

  .description {
    color: var(--ui-muted);
    font-size: var(--ui-text-sm);
    line-height: var(--ui-leading-sm);
  }

  .root[data-disabled] {
    cursor: default;
  }

  .root[data-disabled] :is(.control, .label) {
    opacity: 0.5;
  }

  @media (prefers-reduced-motion: reduce) {
    .thumb,
    .root:active:not([data-disabled], [data-busy]) .thumb {
      transition: background-color var(--ui-dur-instant) var(--ui-ease-color);
    }
    .root:active:not([data-disabled], [data-busy]) .thumb[data-unchecked] {
      inset-inline-end: calc(var(--switch-pad) + var(--switch-travel));
    }
    .root:active:not([data-disabled], [data-busy]) .thumb[data-checked] {
      inset-inline-start: calc(var(--switch-pad) + var(--switch-travel));
    }
    /* The dot stays, still and a little dimmer, so the meaning does too. */
    .root[data-busy-shown] .thumb::after {
      animation: none;
      opacity: 0.7;
    }
  }
}

"use client";

import { useId, useRef, type ChangeEvent, type ChangeEventHandler, type ReactNode, type Ref } from "react";
import { Switch as BaseSwitch } from "@base-ui/react/switch";
import { useDelayedBusy } from "../button/use-delayed-busy";
import styles from "./switch.module.css";

type SwitchProps = Omit<BaseSwitch.Root.Props, "className" | "render" | "nativeButton" | "inputRef" | "onChange"> & {
  /** What the switch turns on. */
  label?: ReactNode;
  /** A second line that says what happens, or why the switch is disabled. */
  description?: ReactNode;
  /** `end` puts the switch at the far edge of a full-width row. */
  side?: "start" | "end";
  /** `md` (default) sits beside a 40px button, `sm` beside a 32px one. */
  size?: "sm" | "md";
  /** The change is being saved. Presses are ignored, focus stays, and after 300ms the thumb shows it's working. */
  busy?: boolean;
  className?: string;
  /** Called with the change event of the hidden checkbox, so `event.target.checked` is the new state. */
  onChange?: ChangeEventHandler<HTMLInputElement>;
  /** The hidden checkbox that carries the form value. */
  ref?: Ref<HTMLInputElement>;
};

/** Base UI's Switch: role="switch", reads as on or off, and submits through a hidden checkbox. */
export function Switch({
  label,
  description,
  side = "start",
  size = "md",
  busy = false,
  className,
  id,
  disabled,
  readOnly,
  onChange,
  onCheckedChange,
  ref,
  ...props
}: SwitchProps) {
  const fallbackId = useId();
  const inputId = id ?? fallbackId;
  const labelId = `${inputId}-label`;
  const descriptionId = `${inputId}-description`;
  const inputRef = useRef<HTMLInputElement>(null);
  const busyShown = useDelayedBusy(busy && !disabled);

  return (
    <label
      className={className ? `${styles.root} ${className}` : styles.root}
      data-side={side}
      data-size={size}
      data-disabled={disabled || undefined}
      data-busy={(busy && !disabled) || undefined}
      data-busy-shown={busyShown || undefined}
    >
      <span className={styles.control}>
        <BaseSwitch.Root
          id={inputId}
          className={styles.track}
          disabled={disabled}
          // Busy, not disabled: presses are ignored but focus stays where it was.
          readOnly={readOnly || busy}
          aria-busy={busy || undefined}
          inputRef={(node) => {
            inputRef.current = node;
            if (typeof ref === "function") ref(node);
            else if (ref) ref.current = node;
          }}
          // The name is the label alone; the description is read after it.
          aria-labelledby={label ? labelId : undefined}
          aria-describedby={description ? descriptionId : undefined}
          onCheckedChange={(checked, details) => {
            onCheckedChange?.(checked, details);
            const input = inputRef.current;
            // Base UI toggles through the hidden checkbox, so its change event is the one callers expect.
            if (onChange && input) {
              const event = details.event;
              onChange({
                type: "change",
                nativeEvent: event,
                target: input,
                currentTarget: input,
                preventDefault: () => event.preventDefault(),
                stopPropagation: () => event.stopPropagation(),
              } as unknown as ChangeEvent<HTMLInputElement>);
            }
          }}
          {...props}
        >
          <BaseSwitch.Thumb className={styles.thumb} />
        </BaseSwitch.Root>
      </span>
      {(label || description) && (
        <span className={styles.text}>
          {label && (
            <span id={labelId} className={styles.label}>
              {label}
            </span>
          )}
          {description && (
            <span id={descriptionId} className={styles.description}>
              {description}
            </span>
          )}
        </span>
      )}
    </label>
  );
}

