@layer components {
  .root {
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
    --connections-pad: var(--ui-space-4);
    --connections-mark: 32px;
    --connections-indent: calc(var(--connections-mark) + var(--ui-space-3));
    /* The head bleeds 8px into the row's padding: card radius minus what's left. */
    --connections-head-radius: calc(var(--ui-radius-lg) - var(--connections-pad) + var(--ui-space-2));
    width: 100%;
    max-width: 520px;
    border-radius: var(--ui-radius-lg);
    background: var(--ui-surface);
    box-shadow: var(--ui-shadow-resting);
    color: var(--ui-foreground);
    font-family: var(--ui-font-sans);
  }

  .list {
    margin: 0;
    padding: 0;
    list-style: none;
  }

  /* Rows open and close through grid-template-rows, so the list never jumps. */
  .row {
    display: grid;
    grid-template-rows: 1fr;
  }

  .row[data-arrived] {
    animation:
      connections-row-open var(--ui-dur-panel) var(--ui-ease-expand),
